@Test(arguments: ["history", "started", "completed"])
@MainActor
func serverMetaIsNotTitle(_ path: String) async throws {
    let json = #"{"id":"meta","type":"user","text":"内部補足","originalText":"内部補足","isMeta":true}"#
    let client = TitleCodexClient()
    let (vm, _) = makeCodexVM(client: client)
    if path == "history" {
        client.threadReadItemsJSON = "[\(json)]"
        await vm.restore(threadId: "thread-meta", approvalPolicy: .named("on-request"), sandbox: .named("workspace-write"))
        #expect(vm.restoreState == .restored)
    } else {
        try await vm.startNew(approvalPolicy: .named("on-request"), sandbox: .named("workspace-write"))
        let threadID = try #require(vm.threadId)
        let item = try TitleLifecycleJSON.threadItem(json)
        if path == "started" {
            client.yieldThread(.itemStarted(threadId: threadID, turnId: "turn-1", item: item))
        } else {
            client.yieldThread(.itemCompleted(threadId: threadID, turnId: "turn-1", item: item))
        }
    }
    try await waitUntil { vm.transcript.contains { $0.id == "meta" } }
    expectState(vm.titleState, "Rose", .flower, "Rose", nil, "server meta excluded")
    await vm.terminate()
}
